/* cppi::2f5b44367e5a832931310d8ec516985d24e379f70a021d967b9a716c725b1659 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2025-04-01'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-12-31'
    ) a
where arrival_time = max_publish

/* cppi::a772df0e389b295ded9e37b3c572ea219c04cdb76af927cd40dee54ab5c93e30 */
with cslDates as (
    select max(business_date) as business_dt, min(business_date) as previous_business_dt
    from (
        select distinct(business_date) from df_trusted_prod.mds_csl_daily_history order by business_date desc limit 2
    )
    ), cslxhis as(
    select *
    from df_trusted_prod.mds_csl_daily_history his
        join cslDates cDates on his.business_date = cDates.business_dt
        where his.business_date = cDates.business_dt or his.business_date = cDates.previous_business_dt
    ), RankedData AS (
    SELECT *,
        ROW_NUMBER() OVER (PARTITION BY id_cppibsec ORDER BY business_date DESC) AS rn
    from cslxhis
    )

select * from RankedData

